        type: "function",
        input: new $ZodTuple({
          type: "tuple",
          items: args[0],
          rest: args[1],
        }),
        output: this._def.output,
      });
    }

    return new F({
      type: "function",
      input: args[0],
      output: this._def.output,
    });
