  const A = z
    .string()
    .transform((val, ctx) => {
      ctx.addIssue({
        code: "custom",
        message: `custom error`,
      });
      ctx.addIssue({
        code: "custom",
        message: `custom error`,
      });
      return val;
    })
    .pipe(z.number() as any);
  expect(A.safeParse("asdf")).toMatchInlineSnapshot(`
    {
      "error": [ZodError: [
      {
        "code": "custom",
        "message": "custom error",
        "path": []
