    }
  `);

  const B = z
    .string()
    .transform((val, ctx) => {
      ctx.issues.push({
        code: "custom",
        message: `custom error`,
        input: val,
      });
      ctx.issues.push({
        code: "custom",
        message: `custom error`,
        input: val,
      });
      return val;
    })
    .pipe(z.number() as any);
  expect(B.safeParse("asdf")).toMatchInlineSnapshot(`
    {
      "error": [ZodError: [
      {
        "code": "custom",
        "message": "custom error",
        "path": []
      },
      {
        "code": "custom",
        "message": "custom error",
        "path": []
      }
    ]],
      "success": false,
    }
  `);

  const C = z
    .string()
    .transform((val, ctx) => {
      ctx.issues.push({
        code: "custom",
