        input: val,
        continue: true,
      });
      ctx.issues.push({
        code: "custom",
        message: `custom error`,
        input: val,
        continue: true,
      });
      return val;
    })
    .pipe(z.number() as any);
  expect(C.safeParse("asdf")).toMatchInlineSnapshot(`
